/**
 * Object storage abstraction for images. Production implementation is a Cloudflare R2
 * bucket binding (works inside Workers with no credentials or SDK); tests use an in-memory
 * fake. Keys are generated by the server, never taken from the client.
 */
export interface ObjectStorage {
  put(key: string, body: Uint8Array, opts: { contentType: string; cacheControl: string }): Promise<void>;
  delete(keys: string[]): Promise<void>;
}

/** The slice of the Workers R2Bucket API we use (structural, so no workers-types dependency). */
export interface R2BucketLike {
  put(
    key: string,
    value: ArrayBuffer | ArrayBufferView | string | null,
    options?: { httpMetadata?: { contentType?: string; cacheControl?: string } },
  ): Promise<unknown>;
  delete(keys: string | string[]): Promise<void>;
}

export function r2Storage(bucket: R2BucketLike): ObjectStorage {
  return {
    async put(key, body, { contentType, cacheControl }) {
      await bucket.put(key, body, { httpMetadata: { contentType, cacheControl } });
    },
    async delete(keys) {
      if (keys.length > 0) await bucket.delete(keys);
    },
  };
}

export const IMAGE_MAX_BYTES = 5 * 1024 * 1024;
export const IMAGES_PER_PRODUCT = 10;

export type SniffedImage = { ext: "jpg" | "png" | "webp"; contentType: "image/jpeg" | "image/png" | "image/webp" };

/**
 * Decide what a file really is from its first bytes, ignoring the client's filename and
 * Content-Type (both attacker-controlled). Only JPEG, PNG and WebP are accepted. SVG is
 * deliberately refused: it can carry scripts.
 */
export function sniffImage(b: Uint8Array): SniffedImage | null {
  if (b.length >= 3 && b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return { ext: "jpg", contentType: "image/jpeg" };
  if (b.length >= 8 && [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a].every((v, i) => b[i] === v)) {
    return { ext: "png", contentType: "image/png" };
  }
  if (
    b.length >= 12 &&
    String.fromCharCode(...b.subarray(0, 4)) === "RIFF" &&
    String.fromCharCode(...b.subarray(8, 12)) === "WEBP"
  ) {
    return { ext: "webp", contentType: "image/webp" };
  }
  return null;
}

/** Random, immutable object names: no user input in the key, so no traversal and no collisions. */
export function newImageKey(prefix: "products" | "categories", ownerId: string, ext: string) {
  return `${prefix}/${ownerId}/${crypto.randomUUID()}.${ext}`;
}

export const IMMUTABLE_CACHE = "public, max-age=31536000, immutable";

export const imageUrl = (base: string | undefined, key: string | null) =>
  key ? `${(base ?? "").replace(/\/+$/, "")}/${key}` : null;
